完整代码package com.y5neko;    import javafx.application.Application;  import javafx.beans.property.ObjectProperty;  import javafx.beans.property.ReadOnlyObjectProperty;  import javafx.beans.property.SimpleObjectProperty;  import javafx.collections.FXCollections;  import javafx.collections.ObservableList;  import javafx.collections.transformation.FilteredList;  import javafx.event.ActionEvent;  import javafx.event.EventHandler;  import javafx.geometry.Insets;  import javafx.scene.Scene;  import javafx.scene.control.ListView;  import javafx.scene.control.ToggleButton;  import javafx.scene.control.ToggleGroup;  import javafx.scene.layout.HBox;  import javafx.scene.layout.VBox;  import javafx.stage.Stage;    import java.util.Arrays;  import java.util.List;  import java.util.function.Predicate;  import java.util.stream.Collectors;    public class FilterListApp extends Application &#123;        @Override      public void start(Stage primaryStage) throws Exception &#123;           //         // 创建测试数据         //         Player[] players = &#123;new Player(&quot;BOS&quot;, &quot;David Ortiz&quot;),                             new Player(&quot;BOS&quot;, &quot;Jackie Bradley Jr.&quot;),                             new Player(&quot;BOS&quot;, &quot;Xander Bogarts&quot;),                             new Player(&quot;BOS&quot;, &quot;Mookie Betts&quot;),                             new Player(&quot;HOU&quot;, &quot;Jose Altuve&quot;),                             new Player(&quot;HOU&quot;, &quot;Will Harris&quot;),                             new Player(&quot;WSH&quot;, &quot;Max Scherzer&quot;),                             new Player(&quot;WSH&quot;, &quot;Bryce Harper&quot;),                             new Player(&quot;WSH&quot;, &quot;Daniel Murphy&quot;),                             new Player(&quot;WSH&quot;, &quot;Wilson Ramos&quot;) &#125;;           //         // 设置模型，该模型是两个玩家列表和一个筛选条件         //         ReadOnlyObjectProperty&lt;ObservableList&lt;Player&gt;&gt; playersProperty =               new SimpleObjectProperty&lt;&gt;(FXCollections.observableArrayList());           ReadOnlyObjectProperty&lt;FilteredList&lt;Player&gt;&gt; viewablePlayersProperty =               new SimpleObjectProperty&lt;FilteredList&lt;Player&gt;&gt;(                     new FilteredList&lt;&gt;(playersProperty.get()                           ));           ObjectProperty&lt;Predicate&lt;? super Player&gt;&gt; filterProperty =            viewablePlayersProperty.get().predicateProperty();             //         // 构建 UI       //       VBox vbox = new VBox();         vbox.setPadding( new Insets(10));         vbox.setSpacing(4);           HBox hbox = new HBox();         hbox.setSpacing( 2 );           ToggleGroup filterTG = new ToggleGroup();           //         // toggleHandler 操作将根据所选的 TB 设置筛选器         //         @SuppressWarnings(&quot;unchecked&quot;)         EventHandler&lt;ActionEvent&gt; toggleHandler = (event) -&gt; &#123;               ToggleButton tb = (ToggleButton)event.getSource();                Predicate&lt;Player&gt; filter = (Predicate&lt;Player&gt;)tb.getUserData();                filterProperty.set( filter );            &#125;;           ToggleButton tbShowAll = new ToggleButton(&quot;Show All&quot;);         tbShowAll.setSelected(true);         tbShowAll.setToggleGroup( filterTG );         tbShowAll.setOnAction(toggleHandler);         tbShowAll.setUserData( (Predicate&lt;Player&gt;) (Player p) -&gt; true);           //         // 从 Player 对象创建不同的团队列表，然后创建         // ToggleButtons（切换按钮）         //         List&lt;ToggleButton&gt; tbs = Arrays.asList( players)               .stream()               .map( (p) -&gt; p.getTeam() )               .distinct()               .map( (team) -&gt; &#123;                  ToggleButton tb = new ToggleButton( team );                  tb.setToggleGroup( filterTG );                  tb.setOnAction( toggleHandler );                  tb.setUserData( (Predicate&lt;Player&gt;) (Player p) -&gt; team.equals(p.getTeam()) );                  return tb;               &#125;)               .collect(Collectors.toList());           hbox.getChildren().add( tbShowAll );         hbox.getChildren().addAll( tbs );           //         // 创建绑定到 viewablePlayers 属性的 ListView       //       ListView&lt;Player&gt; lv = new ListView&lt;&gt;();         lv.itemsProperty().bind( viewablePlayersProperty );           vbox.getChildren().addAll( hbox, lv );           Scene scene = new Scene(vbox);           primaryStage.setScene( scene );         primaryStage.setOnShown((evt) -&gt; &#123;            playersProperty.get().addAll( players );         &#125;);           primaryStage.show();        &#125;        public static void main(String[] args) &#123;         launch(args);      &#125;        static class Player &#123;           private final String team;         private final String playerName;         public Player(String team, String playerName) &#123;            this.team = team;            this.playerName = playerName;         &#125;         public String getTeam() &#123;            return team;         &#125;         public String getPlayerName() &#123;            return playerName;         &#125;         @Override         public String toString() &#123; return playerName + &quot; (&quot; + team + &quot;)&quot;; &#125;      &#125;  &#125;
