package com.y5neko.layout;    import javafx.application.Application;  import javafx.geometry.Insets;  import javafx.geometry.Pos;  import javafx.scene.Scene;  import javafx.scene.control.*;  import javafx.scene.control.cell.PropertyValueFactory;  import javafx.scene.layout.HBox;  import javafx.scene.layout.Priority;  import javafx.stage.Stage;  import javafx.scene.layout.VBox;    public class VBoxAndHBoxApp extends Application &#123;        @Override      public void start(Stage primaryStage) throws Exception &#123;            VBox vbox = new VBox();            HBox topControls = new HBox();          VBox.setMargin( topControls, new Insets(10.0d) );          topControls.setAlignment( Pos.BOTTOM_LEFT );            Button btnRefresh = new Button(&quot;刷新&quot;);          btnRefresh.setOnAction( e -&gt; &#123;              System.out.println(&quot;点击刷新&quot;);          &#125;);            HBox topRightControls = new HBox();          HBox.setHgrow(topRightControls, Priority.ALWAYS );          topRightControls.setAlignment( Pos.BOTTOM_RIGHT );          Hyperlink signOutLink = new Hyperlink(&quot;退出&quot;);          signOutLink.setOnAction( e -&gt; &#123;              System.out.println(&quot;点击退出&quot;);          &#125;);          topRightControls.getChildren().add( signOutLink );            topControls.getChildren().addAll( btnRefresh, topRightControls );            TableView&lt;Customer&gt; tblCustomers = new TableView&lt;&gt;();          tblCustomers.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);          VBox.setMargin( tblCustomers, new Insets(0.0d, 10.0d, 10.0d, 10.0d) );          // setVgrow可以自动调整Vbox子项的大小,防止大小变动时出现空隙          VBox.setVgrow( tblCustomers, Priority.ALWAYS );            TableColumn&lt;Customer, String&gt; lastNameCol = new TableColumn&lt;&gt;(&quot;Last Name&quot;);          lastNameCol.setCellValueFactory(new PropertyValueFactory&lt;&gt;(&quot;lastName&quot;));            TableColumn&lt;Customer, String&gt; firstNameCol = new TableColumn&lt;&gt;(&quot;First Name&quot;);          firstNameCol.setCellValueFactory(new PropertyValueFactory&lt;&gt;(&quot;firstName&quot;));            tblCustomers.getColumns().addAll( lastNameCol, firstNameCol );            Separator sep = new Separator();            HBox bottomControls = new HBox();          bottomControls.setAlignment(Pos.BOTTOM_RIGHT );          VBox.setMargin( bottomControls, new Insets(10.0d) );            Button btnClose = new Button(&quot;关闭&quot;);            btnClose.setOnAction( e -&gt; &#123;              System.out.println(&quot;点击关闭&quot;);              System.exit(0);          &#125;);          bottomControls.getChildren().add( btnClose );            Button btnAdd = new Button(&quot;添加&quot;);          btnAdd.setOnAction( e -&gt; &#123;              System.out.println(&quot;点击添加&quot;);              loadTable(tblCustomers);          &#125;);          bottomControls.getChildren().add( btnAdd );            vbox.getChildren().addAll(                  topControls,                  tblCustomers,                  sep,                  bottomControls          );            Scene scene = new Scene(vbox );            primaryStage.setScene( scene );          primaryStage.setWidth( 800 );          primaryStage.setHeight( 600 );          primaryStage.setTitle(&quot;VBox and HBox App&quot;);          primaryStage.setOnShown( (evt) -&gt; loadTable(tblCustomers) );          primaryStage.show();      &#125;        public static void main(String[] args) &#123;          launch(args);      &#125;        private void loadTable(TableView&lt;Customer&gt; tblCustomers) &#123;          tblCustomers.getItems().add(new Customer(&quot;George&quot;, &quot;Washington&quot;));          tblCustomers.getItems().add(new Customer(&quot;Abe&quot;, &quot;Lincoln&quot;));          tblCustomers.getItems().add(new Customer(&quot;Thomas&quot;, &quot;Jefferson&quot;));      &#125;  &#125;
