package com.y5neko.layout;    import javafx.application.Application;  import javafx.collections.FXCollections;  import javafx.collections.ObservableList;  import javafx.geometry.Insets;  import javafx.scene.Scene;  import javafx.scene.control.*;  import javafx.scene.layout.GridPane;  import javafx.scene.layout.Priority;  import javafx.scene.layout.VBox;  import javafx.stage.Stage;    public class ComplexGridPaneApp extends Application &#123;        @Override      public void start(Stage primaryStage) throws Exception &#123;            VBox vbox = new VBox();            GridPane gp = new GridPane();          gp.setPadding( new Insets(10) );          gp.setHgap( 4 );          gp.setVgap( 10 );            VBox.setVgrow(gp, Priority.ALWAYS );            Label lblTitle = new Label(&quot;Support Ticket&quot;);            Label lblEmail = new Label(&quot;Email&quot;);          TextField tfEmail = new TextField();            Label lblContract = new Label(&quot;Contract&quot;);          TextField tfContract = new TextField();            Label lblPriority = new Label(&quot;Priority&quot;);          ObservableList&lt;String&gt; priorities =              FXCollections.observableArrayList(&quot;Medium&quot;, &quot;High&quot;, &quot;Low&quot;);          ComboBox&lt;String&gt; cbPriority = new ComboBox&lt;&gt;(priorities);            Label lblSeverity = new Label(&quot;Severity&quot;);          ObservableList&lt;String&gt; severities = FXCollections.observableArrayList(&quot;Blocker&quot;, &quot;Workaround&quot;, &quot;N/A&quot;);          ComboBox&lt;String&gt; cbSeverity = new ComboBox&lt;&gt;(severities);            Label lblCategory = new Label(&quot;Category&quot;);          ObservableList&lt;String&gt; categories = FXCollections.observableArrayList(&quot;Bug&quot;, &quot;Feature&quot;);          ComboBox&lt;String&gt; cbCategory = new ComboBox&lt;&gt;(categories);            Label lblProblem = new Label(&quot;Problem&quot;);          TextField tfProblem = new TextField();            Label lblDescription = new Label(&quot;Description&quot;);          TextArea taDescription = new TextArea();            gp.add( lblTitle,       1, 0);  // empty item at 0,0            gp.add( lblEmail,       0, 1);          gp.add(tfEmail,         1, 1);          gp.add( lblContract,    4, 1 );          gp.add( tfContract,     5, 1 );            gp.add( lblPriority,    0, 2);          gp.add( cbPriority,     1, 2);          gp.add( lblSeverity,    2, 2);          gp.add( cbSeverity,     3, 2);          gp.add( lblCategory,    4, 2);          gp.add( cbCategory,     5, 2);            gp.add( lblProblem,     0, 3); gp.add( tfProblem,     1, 3);          gp.add( lblDescription, 0, 4); gp.add( taDescription, 1, 4);            GridPane.setColumnSpan( lblTitle, 5 );          GridPane.setColumnSpan( tfEmail, 3 );          GridPane.setColumnSpan( tfProblem, 5 );          GridPane.setColumnSpan( taDescription, 5 );            Separator sep = new Separator(); // hr            ButtonBar buttonBar = new ButtonBar();          buttonBar.setPadding( new Insets(10) );            Button saveButton = new Button(&quot;Save&quot;);          Button cancelButton = new Button(&quot;Cancel&quot;);            buttonBar.setButtonData(saveButton, ButtonBar.ButtonData.OK_DONE);          buttonBar.setButtonData(cancelButton, ButtonBar.ButtonData.CANCEL_CLOSE);            buttonBar.getButtons().addAll(saveButton, cancelButton);            vbox.getChildren().addAll( gp, sep, buttonBar );            Scene scene = new Scene(vbox);            primaryStage.setTitle(&quot;Grid Pane App&quot;);          primaryStage.setScene(scene);          primaryStage.setWidth( 736 );          primaryStage.setHeight( 414  );          primaryStage.show();        &#125;        public static void main(String[] args) &#123;          launch(args);      &#125;  &#125;
## 网格列约束和行约束
上一篇文章介绍了如何创建一个两列布局，字段名称在左侧，字段值在右侧。 该示例已扩展为向给定行添加更多控件，并在内容中使用跨越句柄间隙。 本文介绍了一对JavaFX类`GridPane`和`ColumnConstraints`。 这些类给予对行或列的附加说明。 在这个例子中，当窗口调整大小时，包含`RowConstraints`的行将被给予所有额外的空间。 这两列将被设置为宽度相等。
这个屏幕截图显示了一个从以前的文章修改的示例。 本文的演示程序有一种旋转的感觉，即字段名与字段值垂直配对（在值的顶部），而不是水平配对。 跨行和跨列用于对齐大于单个单元格的项。

这段代码创建了`Scene`根和`GridPane`对象。
VBox vbox = new VBox();GridPane gp = new GridPane();gp.setPadding( new Insets(10) );gp.setHgap( 4 );gp.setVgap( 10 );VBox.setVgrow(gp, Priority.ALWAYS );
此代码创建本文中使用的UI控件对象。 注意，Priority现在被实现为包含Radiobserver的`VBox`。
Label lblTitle = new Label(&quot;Support Ticket&quot;);Label lblEmail = new Label(&quot;Email&quot;);TextField tfEmail = new TextField();Label lblContract = new Label(&quot;Contract&quot;);TextField tfContract = new TextField();Label lblPriority = new Label(&quot;Priority&quot;);RadioButton rbMedium = new RadioButton(&quot;Medium&quot;);RadioButton rbHigh = new RadioButton(&quot;High&quot;);RadioButton rbLow = new RadioButton(&quot;Low&quot;);VBox priorityVBox = new VBox();priorityVBox.setSpacing( 2 );GridPane.setVgrow(priorityVBox, Priority.SOMETIMES);priorityVBox.getChildren().addAll( lblPriority, rbMedium, rbHigh, rbLow );Label lblSeverity = new Label(&quot;Severity&quot;);ObservableList&lt;String&gt; severities =    FXCollections.observableArrayList(&quot;Blocker&quot;, &quot;Workaround&quot;, &quot;N/A&quot;);ComboBox&lt;String&gt; cbSeverity = new ComboBox&lt;&gt;(severities);Label lblCategory = new Label(&quot;Category&quot;);ObservableList&lt;String&gt; categories =    FXCollections.observableArrayList(&quot;Bug&quot;, &quot;Feature&quot;);ComboBox&lt;String&gt; cbCategory = new ComboBox&lt;&gt;(categories);Label lblProblem = new Label(&quot;Problem&quot;);TextField tfProblem = new TextField();Label lblDescription = new Label(&quot;Description&quot;);TextArea taDescription = new TextArea();
电子邮件、合同、问题和说明的标签和值控制配对放在一个列中。 它们应该采用`GridPane`的整个宽度，因此每个都将其columnSpan设置为2。
GridPane.setColumnSpan( tfEmail, 2 );GridPane.setColumnSpan( tfContract, 2 );GridPane.setColumnSpan( tfProblem, 2 );GridPane.setColumnSpan( taDescription, 2 );
新的优先级无线电水平匹配的严重性和类别的四个控件。 这个rowSpan设置指示JavaFX将包含RadioButton的VBox放在一个高度为四行的合并单元格中。
GridPane.setRowSpan( priorityVBox, 4 );
## 行约束
此时，代码反映了[使用行和列跨越的示例应用程序](https://fxdocs.github.io/docs/html5/#initial_image)中提供的UI屏幕截图。 要重新分配窗体底部的额外空间，请使用RowConstraints对象在`TextArea`的行上设置Priority.ALWAYS。 这将导致`TextArea`增长，以填充可用的空间。
这段代码是一个`RowConstraints`对象到`GridPane`的`TextArea`。 在setter之前，`RowConstraints`对象被分配给所有其他行。 当您指定第12行而没有首先分配对象时，`getRowConstraints()`的set方法将抛出一个索引异常。
RowConstraints taDescriptionRowConstraints = new RowConstraints();taDescriptionRowConstraints.setVgrow(Priority.ALWAYS);for( int i=0; i&lt;13; i++ ) &#123;    gp.getRowConstraints().add( new RowConstraints() );&#125;gp.getRowConstraints().set( 12, taDescriptionRowConstraints );
作为替代语法，有一个setConstraints（）方法可从`GridPane`中获得。 这将传入几个值，并消除了对`TextArea`的专用columnSpan set调用的需要。 前面清单中的`RowConstraints`代码将不会出现在完成的程序中。
gp.setConstraints(taDescription,                  0, 12,                  2, 1,                  HPos.LEFT, VPos.TOP,                  Priority.SOMETIMES, Priority.ALWAYS);
此代码标识（0，12）处的`Node`，即`TextArea`。 `TextArea`将跨越2列，但只有1行。 HPos和Vpos设置为左上角。 最后，hgrow的`Priority`是SOMETIMES，vgrow是ALWAYS。 由于`TextArea`是唯一一行"ALWAYS"，它将获得额外的空间。 如果有其他ALWAYS设置，则空间将在多行之间共享。
